function aggregate(list, strategy) {
    if (!list || list.length === 0) return null;
    switch (strategy) {
        case "mean": return simpleStatistics.mean(list);
        case "geometricMean": return simpleStatistics.geometricMean(list);
        case "harmonicMean": return simpleStatistics.harmonicMean(list);
        case "median": return simpleStatistics.median(list);
        case "min": return simpleStatistics.min(list);
        case "max": return simpleStatistics.max(list);
        case "sum": return simpleStatistics.sumSimple(list);
        default: return list[list.length - 1]; // Fallback (Last value)
    }
}

// Tick engine: gira ogni 1 secondo (1000ms)
var tickId = setInterval(function() {
    var values = context.get("values") || {};
    var redisConfigs = global.get("sensor_configs") || {};
    var now = Date.now();

    // Raggruppiamo i messaggi in uscita per "topic" (Stanza)
    var messagesToSend = {}; 

    for (var topic in values) {
        for (var key in values[topic]) {
            var metricData = values[topic][key];

            // Il timer per questo sensore in questa stanza è scaduto?
            if (now >= metricData.next_send) {

                // Se abbiamo raccolto dei dati...
                if (metricData.payloads.length > 0) {
                    var strategy = redisConfigs[key] && redisConfigs[key].agg_type ? redisConfigs[key].agg_type : "mean";
                    var result = aggregate(metricData.payloads, strategy);

                    if (!messagesToSend[topic]) messagesToSend[topic] = {};
                    messagesToSend[topic][key] = result;
                }

                // Ricalcola il prossimo invio aggiornando dinamicamente il bucket
                var bucket = redisConfigs[key] && redisConfigs[key].bucket_ms ? parseInt(redisConfigs[key].bucket_ms) : 60000;
                metricData.payloads = [];
                metricData.next_send = now + bucket;
            }
        }
    }

    // Invia i messaggi accumulati in questo tick
    for (var t in messagesToSend) {
        // Il topic è sempre nel formato "department:room" nel tuo flusso, lo separo per Memgraph
        let parts = t.split(":"); 

        node.send({ 
            topic: t, 
            payload: messagesToSend[t],
            department: parts[0] || "",
            room: parts[1] || t
        });
    }

    context.set("values", values);
}, 1000); // <-- Risoluzione a 1 secondo

context.set("tickId", tickId);

