data.forEach(row => {
    if (row.node_var) {
        queryParts.push(`  (${row.node_var}:Place {department: '${row.department}', room: '${row.room_name}'})`);
    }
});

// 3. Generate Relationships
data.forEach(row => {
    const targets = row.connected_to;

    // Check if targets exist and is an array with at least one element
    if (Array.isArray(targets) && targets.length > 0) {
        // Format the comment to show targets in uppercase
        const commentTargets = targets.map(t => t.toUpperCase()).join(', ');
        queryParts.push(`\n  // ${row.room_name} -> [${commentTargets}]`);

        targets.forEach(t => {
            queryParts.push(`  (${row.node_var})-[:CONNECTED_TO]->(${t})`);
        });
    }
});

// 4. Build the final query string with correct comma/semicolon placement
let finalQuery = "CREATE\n";

for (let i = 0; i < queryParts.length; i++) {
    const part = queryParts[i];

    // Determine if this is the last actual Cypher command (ignoring comments)
    let isLastStatement = true;
    for (let j = i + 1; j < queryParts.length; j++) {
        if (!queryParts[j].trim().startsWith("//")) {
            isLastStatement = false;
            break;
        }
    }

    if (part.trim().startsWith("//")) {
        // It's a comment, just add a newline
        finalQuery += part + "\n";
    } else {
        // It's a statement, append a comma or semicolon
        finalQuery += part;
        if (!isLastStatement) {
            finalQuery += ",\n";
        } else {
            finalQuery += ";\n";
        }
    }
}

