if (msg.danger !== undefined) {
    let dangerLevel = msg.danger.toLowerCase();

    // Assign the tier based on the YAML mapping.
    // If the danger level isn't found in the mapping, it defaults to 3.
    tier = dangerTiers[dangerLevel] || 3;
}

// Calculate priority based on the tier and the current timestamp
let priority = parseFloat(`${tier}.${Date.now()}`);

// Format the payload for the Redis Priority Queue (ZADD command)
msg.payload = ["room_pq", priority, msg.topic];

msg.topic = null;
return msg;

// 1. Write the query using placeholders (names starting with $)
msg.query = `
  MATCH (n:Place {department: $department, room: $room})
  SET n += $sensors
  RETURN n;
`;

// 2. Pass the actual parameters in msg.params
// (The database will automatically map $room to params.room)
msg.params = {
    department: msg.department,
    room: msg.room,
    sensors: msg.attributes_to_update
};

msg.database = "memgraph";

msg.payload = null
return msg;

if (msg.payload) {
    // 1. Save aggregation configurations (used by the aggregator node)
    if (msg.payload.sensor_configs) {
        global.set('sensor_configs', msg.payload.sensor_configs);
    }

    // 2. Save global settings (thresholds, ttl, excluded sensors)
    if (msg.payload.global_settings) {
        global.set('global_settings', msg.payload.global_settings);
    }

    // 3. Save danger tiers
    if (msg.payload.danger_tiers) {
        global.set('danger_tiers', msg.payload.danger_tiers);
    }

    // 4. Save departments and create reverse maps for sensor mapping
    if (msg.payload.departments) {
        global.set('departments', msg.payload.departments);

        let roomMap = {};
        let sensorMap = {};

        // Loop through the structure to create O(1) fast-read dictionaries
        for (const [deptName, rooms] of Object.entries(msg.payload.departments)) {
            for (const roomObj of rooms) {
                // Map Room -> Department
                roomMap[roomObj.name] = deptName;

                // Map Sensor -> Room
                if (Array.isArray(roomObj.sensors)) {
                    for (const sensor of roomObj.sensors) {
                        sensorMap[sensor] = roomObj.name;
                    }
                }
            }
        }

        // Save the maps ready for the "mapping department" node
        global.set('roomToDepartment', roomMap);
        global.set('sensorToRoom', sensorMap);
    }

    node.warn("YAML configurations loaded and saved in the global context.");
}

return msg;

let topic = (msg.topic !== undefined && msg.topic !== null) ? msg.topic.toString() : "";
if (!topic) return null;

let redisKey = `room:${topic}`;

// Retrieve the parameters from the global context 
// (Ensure the string matches the key saved in the previous node, e.g., "sensor_configs")
let sensor_parameters = global.get("sensor_configs") || {};

if (msg.payload && typeof msg.payload === 'object' && !Array.isArray(msg.payload)) {

    // 1. Register the room as active in Redis if it isn't already
    context.get("active_rooms", "redis", function (err, rooms) {
        rooms = rooms || {};
        if (!rooms[topic]) {
            rooms[topic] = true;
            context.set("active_rooms", rooms, "redis", function (err) {
                if (err) node.error(err);
            });
        }
    });

    // 2. Retrieve current room data and append the new sensor payloads
    context.get(redisKey, "redis", function (err, roomData) {
        roomData = roomData || {};
        let now = Date.now();

        Object.keys(msg.payload).forEach(sensorKey => {
            let val = parseFloat(msg.payload[sensorKey]);

            if (!isNaN(val)) {
                if (!roomData[sensorKey]) {
                    // Apply the bucket_ms from the YAML parameters, fallback to 60000ms (1 minute)
                    let bucket = (sensor_parameters[sensorKey] && sensor_parameters[sensorKey].bucket_ms)
                        ? parseInt(sensor_parameters[sensorKey].bucket_ms)
                        : 60000;

                    roomData[sensorKey] = { payloads: [], next_send: now + bucket };
                }

                roomData[sensorKey].payloads.push(val);
            }
        });

        // 3. Save the updated payloads back to Redis
        context.set(redisKey, roomData, "redis", function (err) {
            if (err) node.error(err);
        });
    });
}

return null;

