function aggregate(list, strategy) {
    if (!list || list.length === 0) return null;
    switch (strategy) {
        case "mean": return simpleStatistics.mean(list);
        case "geometricMean": return simpleStatistics.geometricMean(list);
        case "harmonicMean": return simpleStatistics.harmonicMean(list);
        case "median": return simpleStatistics.median(list);
        case "min": return simpleStatistics.min(list);
        case "max": return simpleStatistics.max(list);
        case "sum": return simpleStatistics.sumSimple(list);
        default: return list[list.length - 1]; // Fallback to the latest recorded value
    }
}

let tickId = setInterval(function () {
    context.get("active_rooms", "redis", function (err, rooms) {
        if (err || !rooms) return;

        // Dynamically fetch the latest parameters on every tick
        let sensor_parameters = global.get("sensor_configs") || {};
        let now = Date.now();

        Object.keys(rooms).forEach(function (topic) {
            let redisKey = `room:${topic}`;

            context.get(redisKey, "redis", function (err, roomData) {
                if (err || !roomData) return;

                let messagesToSend = {};
                let updated = false;

                for (let sensorKey in roomData) {
                    let metricData = roomData[sensorKey];

                    if (now >= metricData.next_send) {
                        if (metricData.payloads.length > 0) {
                            // Apply the aggregation type from the YAML parameters, fallback to "mean"
                            let strategy = (sensor_parameters[sensorKey] && sensor_parameters[sensorKey].agg_type)
                                ? sensor_parameters[sensorKey].agg_type
                                : "mean";
                            let result = aggregate(metricData.payloads, strategy);
                            messagesToSend[sensorKey] = result;
                        }

                        // Calculate the next trigger time based on the YAML bucket configuration
                        let bucket = (sensor_parameters[sensorKey] && sensor_parameters[sensorKey].bucket_ms)
                            ? parseInt(sensor_parameters[sensorKey].bucket_ms)
                            : 60000;

                        metricData.payloads = [];
                        metricData.next_send = now + bucket;
                        updated = true;
                    }
                }

                // If any metrics were aggregated during this tick, send them to the next node
                if (Object.keys(messagesToSend).length > 0) {
                    let parts = topic.split(":");
                    node.send({
                        topic: topic,
                        payload: messagesToSend,
                        department: parts[0] || "",
                        room: parts[1] || topic
                    });
                }

                // Persist the flushed arrays back to Redis
                if (updated) {
                    context.set(redisKey, roomData, "redis", function (err) {
                        if (err) node.error(err);
                    });
                }
            });
        });
    });
}, 1000); // The loop runs every 1 second checking if any bucket timer expired

context.set("tickId", tickId);

